    std::tuple<golang::json::Token, gocpp::error> rec::tokenError(Decoder* dec, unsigned char c)
    {
        gocpp::string context = {};
        //Go switch emulation
        {
            auto condition = dec->tokenState;
            int conditionId = -1;
            if(condition == tokenTopValue) { conditionId = 0; }
            else if(condition == tokenArrayStart) { conditionId = 1; }
            else if(condition == tokenArrayValue) { conditionId = 2; }
            else if(condition == tokenObjectValue) { conditionId = 3; }
            else if(condition == tokenArrayComma) { conditionId = 4; }
            else if(condition == tokenObjectKey) { conditionId = 5; }
            else if(condition == tokenObjectColon) { conditionId = 6; }
            else if(condition == tokenObjectComma) { conditionId = 7; }
            switch(conditionId)
            {
                case 0:
                    context = " looking for beginning of value"_s;
                    break;
                case 1:
                case 2:
                case 3:
                    context = " looking for beginning of value"_s;
                    break;
                case 4:
                    context = " after array element"_s;
                    break;
                case 5:
                    context = " looking for beginning of object key string"_s;
                    break;
                case 6:
                    context = " after object key"_s;
                    break;
                case 7:
                    context = " after object key:value pair"_s;
                    break;
            }
        }
        return {nullptr, gocpp::error(new SyntaxError {"invalid character "_s + quoteChar(c) + context, rec::InputOffset(gocpp::recv(dec))})};
    }

    // More reports whether there is another element in the
    // current array or object being parsed.
    bool rec::More(Decoder* dec)
    {
        auto [c, err] = rec::peek(gocpp::recv(dec));
        return err == nullptr && c != ']' && c != '}';
    }

    std::tuple<unsigned char, gocpp::error> rec::peek(Decoder* dec)
    {
        gocpp::error err = {};
        for(; ; )
        {
            for(auto i = dec->scanp; i < len(dec->buf); i++)
            {
                auto c = dec->buf[i];
                if(isSpace(c))
                {
                    continue;
                }
                dec->scanp = i;
                return {c, nullptr};
            }
            // buffer has been scanned, now report any error
            if(err != nullptr)
            {
                return {0, err};
            }
            err = rec::refill(gocpp::recv(dec));
        }
    }

    // InputOffset returns the input stream byte offset of the current decoder position.
    // The offset gives the location of the end of the most recently returned token
    // and the beginning of the next token.
    int64_t rec::InputOffset(Decoder* dec)
    {
        return dec->scanned + int64_t(dec->scanp);
    }

